		public static void common_sickReaction(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.WazaSickEx sickCode) {
            if (!isPOKEID(args, pokeID))
                return;

            // 019065b0: only reaction types with bit 2 set (or no ITEM_REACTION var at all) check the sickness
            if (Common.GetEventVarIfExist(args, EventVar.Label.ITEM_REACTION, out int reactionType) && (reactionType & 4) == 0)
                return;

            if (common_sickcode_match(args, pokeID, sickCode))
                itemPushRun(args, pokeID);
        }
		public static bool common_useForSick(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.WazaSickEx sickCode, ushort itemID) {
            if (!isPOKEID(args, pokeID))
                return false;

            if (!common_sickcode_match(args, pokeID, sickCode))
                return false;

            var desc = new Section_CureSick.Description();
            desc.targetPokeCount = 1;
            desc.pokeID = pokeID;
            desc.itemID = itemID;
            desc.sick = sickCode;
            desc.targetPokeID[0] = pokeID;
            if (!Common.CureSick(args, desc))
                return false;

            Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
            return true;
        }
		public static bool common_sickcode_match(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Dpr.Battle.Logic.WazaSickEx sickCode) {
            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            switch (sickCode)
            {
                case WazaSickEx.POKEFULL:
                    return bpp.GetPokeSick() != Sick.NONE;

                case WazaSickEx.MENTAL:
                    return calc.CheckMentalSick(bpp) != WazaSick.WAZASICK_NONE;

                case WazaSickEx.POKEFULL_PLUS:
                    return bpp.GetPokeSick() != Sick.NONE || bpp.CheckSick(WazaSick.WAZASICK_KONRAN);

                default:
                    return bpp.CheckSick((WazaSick)sickCode);
            }
        }
