		public static byte common_Himeri_LastWazaIdx(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            byte wazaIdx = bpp.WAZA_SearchIdx(bpp.GetPrevOrgWazaID());
            if (wazaIdx != BattleDefConst.PTL_WAZA_MAX && bpp.WAZA_GetPP(wazaIdx) == 0)
                return wazaIdx;

            return BattleDefConst.PTL_WAZA_MAX;
        }
		public static byte common_Himeri_EnableWazaIdx(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            byte wazaCount = bpp.WAZA_GetCount();
            for (int i = 0; i < wazaCount; i++)
            {
                if (bpp.WAZA_GetPP((byte)i) == 0)
                    return (byte)i;
            }

            return BattleDefConst.PTL_WAZA_MAX;
        }
		public static bool handler_HimeriNomi_common(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, bool fDouble, bool fUseTmp) {
            byte wazaIdx = handler_HimeriNomi_GetTargetWazaIndex(args, pokeID, fUseTmp);
            if (wazaIdx == BattleDefConst.PTL_WAZA_MAX)
                return false;

            byte volume = (byte)(fDouble ? 20 : 10);
            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            var desc = new Section_FromEvent_RecoverPP.Description();
            desc.volume = volume;
            desc.pokeID = pokeID;
            desc.wazaIdx = wazaIdx;
            desc.isSurfacePP = true;
            desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_RecoverPP);
            desc.successMessage.AddArg(pokeID);
            desc.successMessage.AddArg(Common.GetSubID(args));
            desc.successMessage.AddArg((int)bpp.WAZA_GetID(wazaIdx));
            Common.RecoverPP(args, desc);
            return true;
        }
		public static byte handler_HimeriNomi_GetTargetWazaIndex(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, bool fUseTmp) {
            byte wazaIdx = common_Himeri_LastWazaIdx(args, pokeID);
            if (wazaIdx != BattleDefConst.PTL_WAZA_MAX)
                return wazaIdx;

            wazaIdx = common_Himeri_EnableWazaIdx(args, pokeID);
            if (wazaIdx == BattleDefConst.PTL_WAZA_MAX && fUseTmp)
            {
                BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
                byte wazaCount = bpp.WAZA_GetCount();
                for (int i = 0; i < wazaCount; i++)
                {
                    if (bpp.WAZA_GetPPShort((byte)i) != 0)
                        return (byte)i;
                }

                return BattleDefConst.PTL_WAZA_MAX;
            }

            return wazaIdx;
        }
