		public static void handler_common_OrenUse(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, bool fDuble) {
            int recoverHP = common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK);
            // 01908750: lsl by the bool = doubled when fDuble
            if (fDuble)
                recoverHP *= 2;
            ushort itemID = Common.GetSubID(args);
            var desc = new Section_RecoverHP.Description();
            desc.userPokeID = pokeID;
            desc.targetPokeID = pokeID;
            desc.recoverHP = (ushort)recoverHP;
            desc.itemID = itemID;
            desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_RecoverHP);
            desc.successMessage.AddArg(pokeID);
            desc.successMessage.AddArg(itemID);
            if (Common.RecoverHP(args, desc))
                Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
        }
