		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_ObonNomi() => HandlerTable_ObonNomi;
		public static void handler_ObonNomi_Use(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!isPOKEID(args, pokeID))
                return;

            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            uint maxHP = (uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP_BEFORE_G);
            uint mul = Common.GetEventVar(args, EventVar.Label.KINOMI_EFFECT_UP) != 0 ? 2u : 1u;
            byte ratio = (byte)common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK);
            var desc = new Section_RecoverHP.Description();
            desc.userPokeID = pokeID;
            desc.targetPokeID = pokeID;
            desc.itemID = (ushort)ItemNo.OBONNOMI;
            // 01908be0..01908bf8: unsigned (ratio * maxHP) / 100, then * mul
            desc.recoverHP = (ushort)(ratio * maxHP / 100 * mul);
            desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_RecoverHP);
            desc.successMessage.AddArg(pokeID);
            desc.successMessage.AddArg(Common.GetSubID(args));
            if (Common.RecoverHP(args, desc))
                Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
        }
