                return;

            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            uint recoverHP = calc.QuotMaxHP(bpp, (uint)common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK), true);
            // 01909394: lsl by the KINOMI_EFFECT_UP flag = doubled
            if (Common.GetEventVar(args, EventVar.Label.KINOMI_EFFECT_UP) != 0)
                recoverHP <<= 1;

            var recoverDesc = new Section_RecoverHP.Description();
            recoverDesc.userPokeID = pokeID;
            recoverDesc.targetPokeID = pokeID;
            recoverDesc.itemID = itemID;
            recoverDesc.recoverHP = (ushort)recoverHP;
            recoverDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_RecoverHP);
            recoverDesc.successMessage.AddArg(pokeID);
            recoverDesc.successMessage.AddArg(Common.GetSubID(args));
            Common.RecoverHP(args, recoverDesc);

            if (bpp.GetSrcDataConst().JudgeTaste(taste) == TasteJudge.DISLIKE)
            {
                var sickDesc = new Section_AddSick.Description();
                sickDesc.pokeID = pokeID;
                sickDesc.targetPokeID = pokeID;
                sickDesc.sickID = WazaSick.WAZASICK_KONRAN;
                sickDesc.specialMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.BTL_STRID_SET_SeedKonran);
                // shipped: the poke ID is added three times (019094a4 / 019094b4 / 019094c4)
                sickDesc.specialMessage.AddArg(pokeID);
                sickDesc.specialMessage.AddArg(pokeID);
                sickDesc.specialMessage.AddArg(pokeID);
                calc.MakeDefaultWazaSickCont(WazaSick.WAZASICK_KONRAN, bpp, out sickDesc.sickCont);
                Common.AddSick(args, sickDesc);
            }

            Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
            Common.SetWorkValue(args, 0, 1);
        }
