		public static void handler_SutaaNomi(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            var validRankTypes = new WazaRankEffect[rankTypeTbl.Length];
            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            uint count = 0;
            for (int i = 0; i < rankTypeTbl.Length; i++)
            {
                if (bpp.IsRankEffectValid((BTL_POKEPARAM.ValueID)rankTypeTbl[i], 1))
                    validRankTypes[count++] = rankTypeTbl[i];
            }

            if (count == 0)
                return;

            uint idx = calc.GetRand(count);
            common_PinchRankup(args, pokeID, validRankTypes[idx], 2, (ushort)ItemNo.SUTAANOMI);
        }
