		public static void common_PinchRankup(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Pml.WazaData.WazaRankEffect rankType, byte volume, ushort itemID) {
            if (!isPOKEID(args, pokeID))
                return;

            int kinomiEffectUp = Common.GetEventVar(args, EventVar.Label.KINOMI_EFFECT_UP);
            var desc = new Section_FromEvent_RankEffect.Description();
            desc.targetPokeCount = 1;
            desc.pokeID = pokeID;
            desc.targetPokeID[0] = pokeID;
            desc.rankType = rankType;
            // 0190a134: volume << (KINOMI_EFFECT_UP != 0)
            desc.rankVolume = (sbyte)(volume << (kinomiEffectUp != 0 ? 1 : 0));
            desc.itemID = itemID;
            if (Common.RankEffect(args, desc))
                Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
        }
