		public static bool common_WeakAff_Relieve(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, byte type, bool fIgnoreAffine) {
            if (!isPOKEID_DEF(args, pokeID))
                return false;

            if (getWAZA_TYPE(args) != type)
                return false;

            if (getMIGAWARI_FLAG(args))
                return false;

            if (!fIgnoreAffine && getTYPEAFF(args) < TypeAffinity.AffinityID.TYPEAFF_2)
                return false;

            if (Common.GetWorkValue(args, 0) != 0)
                return false;

            // FX32 0.5 (0.25 with KINOMI_EFFECT_UP)
            Common.MulEventVar(args, EventVar.Label.RATIO, Common.GetEventVar(args, EventVar.Label.KINOMI_EFFECT_UP) != 0 ? 1024 : 2048);
            Common.SetWorkValue(args, 0, 1);

            var desc = new Section_FromEvent_SetTurnFlag.Description();
            desc.pokeID = pokeID;
            desc.flag = BTL_POKEPARAM.TurnFlag.TURNFLG_RESERVE_ITEM_SPEND;
            Common.SetTurnFlag(args, desc);
            return true;
        }
