            if (Common.GetWorkValue(args, 0) == 0)
                return;

            if (!isPOKEID_DEF(args, pokeID))
                return;

            Common.SetWorkValue(args, 0, 0);
            Common.EnableWazaSubEffect(args, pokeID);

            var desc = new Section_FromEvent_ConsumeItem.Description();
            desc.userPokeID = pokeID;
            desc.isUseActionDisable = true;
            desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.Item_DamageShrink);
            desc.successMessage.AddArg(pokeID);
            desc.successMessage.AddArg(Common.GetSubID(args));
            Common.ConsumeItem(args, desc);
        }
