		public static void common_DamageReact(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, uint n, bool fCheckReactionType) {
            if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
                return;

            bool isReact;
            if (fCheckReactionType)
                isReact = common_DamageReactCheck(args, pokeID, n);
            else
                isReact = common_DamageReactCheckCore(args, pokeID, n);

            if (isReact)
                itemPushRun(args, pokeID);
        }
		public static bool common_DamageReactCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, uint n) {
            if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
                return false;

            // 0190d090: bit 0 of the reaction type
            if ((Common.GetEventVar(args, EventVar.Label.ITEM_REACTION) & 1) == 0)
                return false;

            return common_DamageReactCheckCore(args, pokeID, n);
        }
		public static bool common_DamageReactCheckCore(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, uint n) {
            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            // 0190d170..0190d198: KUISINBOU halves the divisor when it is above 2; never below 1
            if (bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_TOKUSEI_EFFECTIVE) == (int)TokuseiNo.KUISINBOU && n > 2)
                n >>= 1;
            if (n == 0)
                n = 1;

            if ((uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_MAX_HP) < 2)
                return false;

            uint hp = (uint)bpp.GetValue(BTL_POKEPARAM.ValueID.BPP_HP);
            return hp <= calc.QuotMaxHP_Zero(bpp, n);
        }
