		public static void handler_IbanNomi_SpPriorityCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (Common.GetEventVar(args, EventVar.Label.SP_PRIORITY) != (int)BtlSpecialPri.BTL_SPPRI_DEFAULT)
                return;

            if (!isPOKEID(args, pokeID))
                return;

            // 0190d388: called on args.pPokeActionContainer directly (no Common class-init test)
            if (args.pPokeActionContainer.IsAllActDoneByPokeID(pokeID))
                return;

            if (!common_DamageReactCheckCore(args, pokeID, 4))
                return;

            if (Common.RewriteEventVar(args, EventVar.Label.SP_PRIORITY, (int)BtlSpecialPri.BTL_SPPRI_HIGH))
                itemPushRun(args, pokeID);
        }
