		public static void handler_MikuruNomi_Use(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!isPOKEID(args, pokeID))
                return;

            int kinomiEffectUp = Common.GetEventVar(args, EventVar.Label.KINOMI_EFFECT_UP);
            var desc = new Section_AddSick.Description();
            desc.pokeID = pokeID;
            desc.targetPokeID = pokeID;
            desc.sickID = WazaSick.WAZASICK_HITRATIO_UP;
            // hit ratio ×1.2 (×1.4 with KINOMI_EFFECT_UP)
            desc.sickCont = SICKCONT.MakePermanentParam(pokeID, (ushort)(kinomiEffectUp != 0 ? 140 : 120));
