            desc.specialMessage.AddArg(pokeID);
            desc.specialMessage.AddArg(Common.GetSubID(args));
            if (Common.AddSick(args, desc))
                Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
        }
