		public static void handler_JapoNomi_Damage(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            common_JapoRenbu_Reaction(args, pokeID, WazaDamageType.PHYSIC);
        }
		public static void handler_JapoNomi_Use(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!isPOKEID(args, pokeID))
                return;

            // work[0] = attacker poke ID + 1 (set by common_JapoRenbu_Reaction)
            byte work = (byte)Common.GetWorkValue(args, 0);
            if (work == 0)
                return;

            byte attackerID = (byte)(work - 1);
            BTL_POKEPARAM attacker = Common.GetPokeParam(args, attackerID);
            if (attacker.IsDead())
                return;

            byte denom = (byte)common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK);
            if (Common.GetEventVar(args, EventVar.Label.KINOMI_EFFECT_UP) != 0)
                denom = (byte)(denom >> 1);

            var desc = new Section_FromEvent_Damage.Description();
            desc.pokeID = pokeID;
            desc.targetPokeID = attackerID;
            desc.damage = (ushort)calc.QuotMaxHP(attacker, denom, true);
            desc.damageCause = DamageCause.JAPO_RENBU;
            desc.damageCausePokeID = pokeID;
            desc.disableDeadProcess = true;
            desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_DamageOpponent);
            desc.successMessage.AddArg(attackerID);
            desc.successMessage.AddArg(pokeID);
            desc.successMessage.AddArg(Common.GetSubID(args));
            if (Common.Damage(args, desc))
                Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
        }
		public static void common_JapoRenbu_Reaction(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, global::Pml.WazaData.WazaDamageType dmgType) {
            if (!isPOKEID_DEF(args, pokeID))
                return;

            if (getMIGAWARI_FLAG(args))
                return;

            if (tables.IsDelayAttackWaza((WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID)))
                return;

            if (Common.GetEventVar_DAMAGE_TYPE(args) != dmgType)
                return;

            args.pMyFactor.SetRecallEnable();
            Common.SetWorkValue(args, 0, getPOKEID_ATK(args) + 1);

            var desc = new Section_UseItemEquip.Description();
            desc.userPokeID = pokeID;
            desc.isUseDead = true;
            Common.UseItem(args, desc);
        }
