		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_SenseiNoTume() => HandlerTable_SenseiNoTume;
		public static void handler_SenseiNoTume_SpPriorityCheck(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (Common.GetEventVar(args, EventVar.Label.SP_PRIORITY) != (int)BtlSpecialPri.BTL_SPPRI_DEFAULT)
                return;

            if (!isPOKEID(args, pokeID))
                return;

            if (args.pPokeActionContainer.IsAllActDoneByPokeID(pokeID))
                return;

            if (Common.GetWorkValue(args, WIDX_SENSEINOTUME_RAND_CHECK_DONE) == 0)
            {
                bool isOccur = isOccurPer(args, (byte)common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK));
                Common.SetWorkValue(args, WIDX_SENSEINOTUME_RAND_CHECK_CLEAR, isOccur ? 1 : 0);
                Common.SetWorkValue(args, WIDX_SENSEINOTUME_RAND_CHECK_DONE, 1);
            }

            if (Common.GetWorkValue(args, WIDX_SENSEINOTUME_RAND_CHECK_CLEAR) == 0)
                return;

            if (!Common.RewriteEventVar(args, EventVar.Label.SP_PRIORITY, (int)BtlSpecialPri.BTL_SPPRI_HIGH))
                return;

            if (Common.GetWorkValue(args, WIDX_SENSEINOTUME_USE_DONE) == 0)
                itemPushRun(args, pokeID);
        }
