            desc.pokeID = pokeID;
            desc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_PriorityUpOnce);
            desc.message.AddArg(pokeID);
            desc.message.AddArg(Common.GetSubID(args));
            Common.Message(args, desc);
            Common.SetWorkValue(args, WIDX_SENSEINOTUME_USE_DONE, 1);
            Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
        }
