		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_MetroNome() => HandlerTable_MetroNome;
		public static void handler_MetroNome(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!isPOKEID_ATK(args, pokeID))
                return;

            WazaNo waza = (WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID);
            if (tables.IsDelayAttackWaza(waza))
                return;

            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            uint counter = bpp.GetWazaContCounter();
            if (counter == 0 || bpp.GetPrevWazaID() != waza)
                return;

            // 01914070..0191407c: 32-bit (param * counter + 100), capped at 200 (`csel lt`), then inlined FX32.CONST / 100
            int ratio = common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK) * (int)counter + 100;
            if (ratio >= 200)
                ratio = 200;
            Common.MulEventVar(args, EventVar.Label.RATIO, FX32.CONST((float)ratio) / 100);
        }
