        }
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_KaigaraNoSuzu() => HandlerTable_KaigaraNoSuzu;
		public static void handler_KaigaraNoSuzu(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!isPOKEID_ATK(args, pokeID))
                return;

            if (Common.GetEventVar(args, EventVar.Label.DELAY_ATTACK_FLAG) != 0)
                return;

            uint damage = (uint)Common.GetEventVar(args, EventVar.Label.DAMAGE);
            if (damage == 0)
                return;

            uint recoverHP = damage;
            uint denom = (uint)common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK);
            // 01914594: a real zero test before the udiv
            if (denom != 0)
                recoverHP = damage / denom;
            if (recoverHP == 0)
                recoverHP = 1;

            ushort itemID = Common.GetSubID(args);
            var desc = new Section_RecoverHP.Description();
            desc.userPokeID = pokeID;
            desc.targetPokeID = pokeID;
            desc.recoverHP = (ushort)recoverHP;
            desc.itemID = itemID;
            desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_RecoverLittle);
            desc.successMessage.AddArg(pokeID);
            desc.successMessage.AddArg(itemID);
            Common.RecoverHP(args, desc);
        }
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_HikariNoNendo() => HandlerTable_HikariNoNendo;
		public static void handler_HikariNoNendo(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!isPOKEID(args, pokeID))
                return;

            // 019147ac: mask 0x20003 = REFLECTOR, HIKARINOKABE, AURORAVEIL
            BtlSideEffect sideEffect = (BtlSideEffect)Common.GetEventVar(args, EventVar.Label.SIDE_EFFECT);
            if (sideEffect != BtlSideEffect.BTL_SIDEEFF_REFLECTOR && sideEffect != BtlSideEffect.BTL_SIDEEFF_HIKARINOKABE && sideEffect != BtlSideEffect.BTL_SIDEEFF_AURORAVEIL)
                return;

            BTL_SICKCONTOBJ sickCont = getSickContAddress(args);
            byte incTurn = (byte)common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK);
            SICKCONT.IncTurn(ref sickCont.value, incTurn);
            SICKCONT.AddParam(ref sickCont.value, incTurn);
        }
