		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_KuroiHedoro() => HandlerTable_KuroiHedoro;
		public static void handler_KuroiHedoro(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!isPOKEID(args, pokeID))
                return;

            if (Common.CheckShowDown(args))
                return;

            BTL_POKEPARAM bpp = Common.GetPokeParam(args, pokeID);
            ushort itemID = Common.GetSubID(args);
            if (PokeTypePair.IsMatch(bpp.GetPokeType(), (byte)Pml.PokeType.DOKU))
            {
                uint denom = (uint)common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK);
                var recoverDesc = new Section_RecoverHP.Description();
                recoverDesc.userPokeID = pokeID;
                recoverDesc.targetPokeID = pokeID;
                recoverDesc.recoverHP = (ushort)calc.QuotMaxHP(bpp, denom, true);
                recoverDesc.itemID = itemID;
                recoverDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_RecoverLittle);
                recoverDesc.successMessage.AddArg(pokeID);
                recoverDesc.successMessage.AddArg(itemID);
                Common.RecoverHP(args, recoverDesc);
            }
            else
            {
                var damageDesc = new Section_FromEvent_Damage.Description();
                damageDesc.pokeID = pokeID;
                damageDesc.targetPokeID = pokeID;
                damageDesc.damage = (ushort)calc.QuotMaxHP(bpp, 8, true);
                damageDesc.damageCause = DamageCause.KUROIHEDORO;
                damageDesc.damageCausePokeID = pokeID;
                damageDesc.exEffectPlayMode = Section_FromEvent_Damage.EffectPlayMode.ENABLE;
                damageDesc.exEffectNo = (ushort)BtlEff.BTLEFF_SOUBI_ITEM;
                damageDesc.exEffectPos_from = Common.PokeIDtoPokePos(args, pokeID);
                damageDesc.exEffectPos_to = BtlPokePos.POS_NULL;
                damageDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.UseItem_Damage);
                damageDesc.successMessage.AddArg(pokeID);
                damageDesc.successMessage.AddArg(itemID);
                Common.Damage(args, damageDesc);
            }
        }
