		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_GotugotuMet() => HandlerTable_GotugotuMet;
		public static void handler_GotugotuMet(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            // 0191aa10: POKEID_DEF / MIGAWARI_FLAG / POKEID_ATK are read directly (no isPOKEID_DEF / getMIGAWARI_FLAG flags)
            if (Common.GetEventVar(args, EventVar.Label.POKEID_DEF) != pokeID)
                return;

            if (Common.GetEventVar(args, EventVar.Label.MIGAWARI_FLAG) != 0)
                return;

            if (Common.GetEventVar(args, EventVar.Label.WAZA_TOUCH_FLAG) == 0)
                return;

            var desc = new Section_FromEvent_Damage.Description();
            desc.pokeID = pokeID;
            desc.targetPokeID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
            BTL_POKEPARAM attacker = Common.GetPokeParam(args, desc.targetPokeID);
            desc.damage = (ushort)calc.QuotMaxHP(attacker, (byte)common_GetItemParam(args.pMyFactor, Pml.Item.ItemData.PrmID.ATTACK), true);
            desc.damageCause = DamageCause.GOTUGOTUMETTO;
            desc.damageCausePokeID = pokeID;
            desc.disableDeadProcess = true;
            desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.GotuGotuMet);
            desc.successMessage.AddArg(desc.targetPokeID);
            Common.Damage(args, desc);
        }
		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_Huusen() => HandlerTable_Huusen;
		public static void handler_Huusen_MemberIn(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!isPOKEID(args, pokeID))
                return;

            if (Common.CheckFieldEffect(args, EffectType.EFF_JURYOKU))
                return;

