		public static global::Dpr.Battle.Logic.EventFactor.EventHandlerTable[] ADD_RedCard() => HandlerTable_RedCard;
		public static void handler_RedCard(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (!Common.CheckTargetPokeID(args, pokeID))
                return;

            byte attackerID = (byte)Common.GetEventVar(args, EventVar.Label.POKEID_ATK);
            if (Common.GetExistFrontPokePos(args, attackerID) == BtlPokePos.POS_NULL)
                return;

            if (Common.GetEventVar(args, EventVar.Label.DELAY_ATTACK_FLAG) != 0)
                return;

            if (!Common.IsExistBenchPoke(args, attackerID))
                return;

            if (!Common.CheckChangeEnablePokeExist(args, attackerID))
                return;

            if (Common.CheckShowDown(args))
                return;

            var consumeDesc = new Section_FromEvent_ConsumeItem.Description();
            consumeDesc.userPokeID = pokeID;
            consumeDesc.isConsumeMessageEnable = true;
            consumeDesc.successMessage.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.RedCard);
            consumeDesc.successMessage.AddArg(pokeID);
            consumeDesc.successMessage.AddArg(attackerID);
            Common.ConsumeItem(args, consumeDesc);

            var pushOutDesc = new Section_PushOut.Description();
            pushOutDesc.attackerID = pokeID;
            pushOutDesc.isIgnoreLevel = true;
            pushOutDesc.targetID = attackerID;
            pushOutDesc.effectNo = (ushort)BtlEff.BTLEFF_POKEMON_MODOSU;
            Common.PushOut(args, pushOutDesc);
        }
