            if (!Common.CheckTargetPokeID(args, pokeID))
                return;

            if (Common.GetEventVar(args, EventVar.Label.DELAY_ATTACK_FLAG) != 0)
                return;

            if (Common.CheckFreeFallPoke(args, pokeID))
                return;

            if (Common.CheckShowDown(args))
                return;

            if (Common.CheckMemberOutInterruptActionProceeding(args))
                return;

            if (!Common.IsExistBenchPoke(args, pokeID))
                return;

            if (!Common.CheckChangeEnablePokeExist(args, pokeID))
                return;

            if (!Common.IsExistPokeChangeRequest(args))
                itemPushRun(args, pokeID);
        }
		public static void handler_DassyutuButton_Use(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            // 0191d130: POKEID read directly (no isPOKEID flag); the message desc keeps its default pokeID
            if (Common.GetEventVar(args, EventVar.Label.POKEID) != pokeID)
                return;

            var msgDesc = new Section_FromEvent_Message.Description();
            msgDesc.message.Setup(BtlStrType.BTL_STRTYPE_SET, BTL_STRID_SET.DassyutuPod);
            msgDesc.message.AddArg(pokeID);
            Common.Message(args, msgDesc);

            var changeDesc = new Section_FromEvent_MemberChange.Description();
            changeDesc.outPokeID = pokeID;
            changeDesc.isInterruptDisable = true;
            if (!Common.MemberChange(args, changeDesc))
                return;

            Common.RewriteEventVar(args, EventVar.Label.NEED_ITEM_CONSUME_MESSAGE_DISPLAY, TRUE);
            Common.RewriteEventVar(args, EventVar.Label.ITEMUSE_FLAG, TRUE);
        }
