            if (!isPOKEID(args, pokeID))
                return;

            if (Common.GetEventVar(args, EventVar.Label.VOLUME) < 0)
                Common.SetWorkValue(args, 0, 1);
        }
		public static void handler_DassyutuPack_Launch(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID) {
            if (Common.GetWorkValue(args, 0) == 0)
                return;

            Common.SetWorkValue(args, 0, 0);

            if (Common.CheckFreeFallPoke(args, pokeID))
                return;

            if (Common.CheckShowDown(args))
                return;

            if (Common.CheckMemberOutInterruptActionProceeding(args))
                return;

            if (!Common.IsExistBenchPoke(args, pokeID))
                return;

            if (!Common.CheckChangeEnablePokeExist(args, pokeID))
                return;

            if (!Common.IsExistPokeChangeRequest(args))
                itemPushRun(args, pokeID);
        }
