		public static void common_Juel_Decide(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, byte type) {
            if (!isPOKEID_ATK(args, pokeID))
                return;

            if (getWAZA_TYPE(args) != type)
                return;

            WazaNo waza = (WazaNo)Common.GetEventVar(args, EventVar.Label.WAZAID);
            if (!WAZADATA.IsDamage(waza))
                return;

            if (tables.IsCombiWaza(waza))
                return;

            if (args.pMyFactor.IsIsolateMode())
                return;

            args.pMyFactor.ConvertForIsolate();

            var desc = new Section_FromEvent_ConsumeItem.Description();
            desc.userPokeID = pokeID;
            desc.isConsumeMessageEnable = true;
            desc.successMessage.Setup(BtlStrType.BTL_STRTYPE_STD, BTL_STRID_STD.Juel);
            desc.successMessage.AddArg(Common.GetSubID(args));
            desc.successMessage.AddArg((int)waza);
            Common.ConsumeItem(args, desc);
            Common.SetWorkValue(args, 0, JUEL_SEQ_STANDBY);
        }
		public static void common_Juel_Power(in global::Dpr.Battle.Logic.EventFactor.EventHandlerArgs args, byte pokeID, byte type) {
            if (!isPOKEID_ATK(args, pokeID))
                return;

            if (getWAZA_TYPE(args) != type)
                return;

            // FX32 1.3 (0x14cd)
            if (Common.GetWorkValue(args, 0) == JUEL_SEQ_STANDBY)
                Common.MulEventVar(args, EventVar.Label.WAZA_POWER_RATIO, 5325);
        }
